-- The Anvil library: platform-wide tasks and boards clans browse and import (lib/libraryTasks,
-- lib/libraryBoards), and suggestions for it that staff review (lib/libraryProposals).
--
-- Seeds the task library from the starter tasks every clan used to copy from a file, and the board
-- library from the three starter boards plus their Leagues version. Clans' existing copies of those
-- tasks are linked to the library task they came from: an untouched copy (matching the original or
-- the corrected task) FOLLOWS Anvil from here on and is brought up to the corrected version; an
-- edited copy is linked but stays the clan's.
CREATE TABLE IF NOT EXISTS "library_tasks" (
  "id" serial PRIMARY KEY NOT NULL,
  "key" text NOT NULL,
  "label" text NOT NULL,
  "description" text,
  "category" text,
  "tile_type" text DEFAULT 'standard' NOT NULL,
  "points" integer DEFAULT 0 NOT NULL,
  "config" text NOT NULL,
  "version" integer DEFAULT 1 NOT NULL,
  "archived" boolean DEFAULT false NOT NULL,
  "created_by_user_id" integer REFERENCES "users"("id") ON DELETE SET NULL,
  "updated_by_user_id" integer REFERENCES "users"("id") ON DELETE SET NULL,
  "created_at" text NOT NULL,
  "updated_at" text NOT NULL
);--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "library_tasks_key_idx" ON "library_tasks" USING btree ("key");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "library_tasks_category_idx" ON "library_tasks" USING btree ("category");--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "library_boards" (
  "id" serial PRIMARY KEY NOT NULL,
  "title" text NOT NULL,
  "description" text DEFAULT '' NOT NULL,
  "origin" text DEFAULT 'community' NOT NULL,
  "clan_id" integer REFERENCES "clans"("id") ON DELETE CASCADE,
  "published_by_user_id" integer REFERENCES "users"("id") ON DELETE SET NULL,
  "mode" text NOT NULL,
  "board_size" integer NOT NULL,
  "tiles" text NOT NULL,
  "audience" text DEFAULT 'mixed' NOT NULL,
  "tags" jsonb DEFAULT '[]'::jsonb NOT NULL,
  "suggested_days" integer,
  "teams_min" integer,
  "teams_max" integer,
  "status" text DEFAULT 'published' NOT NULL,
  "version" integer DEFAULT 1 NOT NULL,
  "use_count" integer DEFAULT 0 NOT NULL,
  "created_at" text NOT NULL,
  "updated_at" text NOT NULL
);--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "library_boards_origin_idx" ON "library_boards" USING btree ("origin","status");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "library_boards_clan_idx" ON "library_boards" USING btree ("clan_id");--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "library_proposals" (
  "id" serial PRIMARY KEY NOT NULL,
  "kind" text NOT NULL,
  "target_task_id" integer REFERENCES "library_tasks"("id") ON DELETE SET NULL,
  "target_board_id" integer REFERENCES "library_boards"("id") ON DELETE SET NULL,
  "base_version" integer,
  "payload" text NOT NULL,
  "note" text,
  "proposer_user_id" integer NOT NULL REFERENCES "users"("id") ON DELETE CASCADE,
  "clan_id" integer REFERENCES "clans"("id") ON DELETE SET NULL,
  "status" text DEFAULT 'pending' NOT NULL,
  "review_note" text,
  "reviewed_by_user_id" integer REFERENCES "users"("id") ON DELETE SET NULL,
  "created_at" text NOT NULL,
  "reviewed_at" text
);--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "library_proposals_status_idx" ON "library_proposals" USING btree ("status");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "library_proposals_proposer_idx" ON "library_proposals" USING btree ("proposer_user_id","status");--> statement-breakpoint
ALTER TABLE "tile_library" ADD COLUMN IF NOT EXISTS "source_task_id" integer REFERENCES "library_tasks"("id") ON DELETE SET NULL;--> statement-breakpoint
ALTER TABLE "tile_library" ADD COLUMN IF NOT EXISTS "source_version" integer;--> statement-breakpoint
ALTER TABLE "tile_library" ADD COLUMN IF NOT EXISTS "follows_source" boolean DEFAULT false NOT NULL;--> statement-breakpoint
ALTER TABLE "events" ADD COLUMN IF NOT EXISTS "library_board_id" integer REFERENCES "library_boards"("id") ON DELETE SET NULL;--> statement-breakpoint
